/* aesthetic flow v2.22.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-line: #e9e9e9;
  --ae-ok: #15714b;
  --ae-err: #a84138;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-line-dark: #262626;
  --ae-ok-dark: #6fd2a8;
  --ae-err-dark: #e58379;
  --ae-w-medium: 550;
  --ae-w-black: 800;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
    --ae-line: var(--ae-line-dark);
    --ae-ok: var(--ae-ok-dark);
    --ae-err: var(--ae-err-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
  --ae-line: var(--ae-line-dark);
  --ae-ok: var(--ae-ok-dark);
  --ae-err: var(--ae-err-dark);
}

.ae-icon {
width: 1.2em;
  height: 1.2em;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
  vertical-align: -0.2em;
}

.ae-ok {
color: var(--ae-ok);
}

.ae-flow {
display: block;
  width: 100%;
  height: auto;
}

.ae-node {
fill: var(--ae-surface);
  stroke: var(--ae-line);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.ae-node.is-done {
stroke: var(--ae-ink-muted);
}

.ae-node.is-active {
stroke: var(--ae-accent);
  stroke-width: 1.5;
}

.ae-node.is-locked {
fill: var(--ae-wash);
  stroke: var(--ae-ink-faint);
  stroke-dasharray: 3 3;
}

.ae-node.is-failed {
stroke: var(--ae-err);
}

.ae-node-label {
fill: var(--ae-ink);
  font-family: var(--ae-font);
  font-size: 13px;
  font-weight: var(--ae-w-medium);
}

.ae-node-label.is-active {
fill: var(--ae-accent);
  font-weight: var(--ae-w-black);
}

.ae-node-label.is-locked {
fill: var(--ae-ink-faint);
  font-weight: var(--ae-w-regular);
}

.ae-wire {
fill: none;
  stroke: var(--ae-line);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.ae-wire.is-reached {
stroke: var(--ae-ink-muted);
}

.ae-wire.is-active {
stroke: var(--ae-accent);
}

.ae-wire.is-locked {
stroke: var(--ae-ink-faint);
  stroke-dasharray: 3 3;
}
